import{z as B,x as l,o as E,c as A,q as t,j as s,D as e,d as i,s as n,S as o}from"./chunks/framework.C8m1ZpeB.js";const m=JSON.parse('{"title":"SIP vs 直连行情","description":"","frontmatter":{"title":"SIP vs 直连行情","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/sip-vs-direct.md","filePath":"quant/sip-vs-direct.md","lastUpdated":1791413859000}'),d={name:"quant/sip-vs-direct.md"};function p(S,a,P,c,h,I){const r=l("Mermaid");return E(),A("div",null,[a[2]||(a[2]=t('<h1 id="sip-vs-直连行情" tabindex="-1">SIP vs 直连行情 <a class="header-anchor" href="#sip-vs-直连行情" aria-label="Permalink to &quot;SIP vs 直连行情&quot;">​</a></h1><div class="epigraph"><p>全国行情汇总会出一条受监管的 SIP；各交易所另售直连馈送。两者的价格最终都会打印，但到达时刻与中间状态不同。研究用 SIP 当「市场」，交易用直连当「可交易」，中间的差是制度，不是噪声。</p><footer>—— 据 Reg NMS 下 SIP 的制度角色；对照 Hasbrouck 对微观结构数据来源与延迟的讨论</footer></div><p>附录「交易所与数据源对照」从馈送契约起。<a href="/quant/market-fragmentation">市场分割与 NBBO</a>已经说明保护报价要被拼成全国最优。本课的缺口是两条管道：SIP（证券信息处理器）汇集各所报价与成交再广播；直连（direct feed）从单一场所或一簇场所直达用户。Ding、Hanna 与 Hendershott 等经验工作表明 SIP 相对直连存在延迟，NBBO 在两条管道上会短暂分叉。本课写对象差异与研究选择，不写如何利用延迟跨所交易。后课时钟与对时是测量分叉的前提。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>SIP 的制度功能是给公众一个统一的、受保护的行情与成交磁带。直连的功能是给延迟敏感用户本所（及购买的多所）的更快增量。内容不是简单的「SIP 是直连的延迟版」：汇总、容量节流、不同字段、成交与报价的打包，都会改变你看到的状态。用 SIP 的 NBBO 去标记直连成交的有效价差，中点可能已过时，ES 被系统性扭曲。用直连合成的「快 NBBO」去评价监管执行质量，对照的又不是受保护的那一条。缺口是声明：这项研究的行情契约是 SIP、直连还是两者都存。</p><p><span class="marginnote">术语翻译：SIP（Securities Information Processor）是「全国行情汇总广播」——各交易所把报价与成交汇到统一出口再发布，像一块面向公众的官方公告牌；直连则是你从某家交易所机房拉一根专线，拿该所最快的第一手数据。</span></p><p>碎片化课问设计；本课问你磁盘上的字节来自哪根管子。没有声明的「我们用 TAQ」仍可能是 SIP 磁带。直连 L3 与 SIP 的 L1 不可互相替代去重建队列。</p><p><span class="marginnote">常见误区：「我们用的是 TAQ，所以没这个问题」。TAQ 本质上是 SIP 磁带的学术版；若研究关心执行或延迟，用它就等于默认接受了 SIP 的到达时刻。数据来自哪根管道必须写进研究契约，不能靠默认。</span></p><h3 id="延迟、完整与成本是三件事" tabindex="-1">延迟、完整与成本是三件事 <a class="header-anchor" href="#延迟、完整与成本是三件事" aria-label="Permalink to &quot;延迟、完整与成本是三件事&quot;">​</a></h3><p>直连更快，但不自动更完整：你没买的场所就没有。SIP 更慢，但在制度上覆盖保护报价。研究全国质量，SIP 或官方磁带往往更合适；研究本所队列，必须直连。两者都买时，分叉时间序列本身是对象：锁定交叉在直连上出现、在 SIP 上尚未出现的占比。这是后课 NBBO 构造的输入。</p><p><span class="marginnote">A 股没有美国式的 SIP vs 十几家直连。对照应改成：交易所官方行情 vs 行情商转发 vs 经纪商推送。延迟结构类似，法律保护报价的含义不同。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>元数据：每条报价/成交记录 <code>source ∈ {SIP, direct, broker}</code>、场所、时间戳类型。分析有效价差时，中点与成交必须同源，或明确做跨源对照实验。对照实验：同一成交，分别用 SIP 中点与直连合成中点算 ES，报告差的分布。差的中位若达到一个 tick，任何「市场变便宜了」的结论都依赖源。</p><p>容量：SIP 在高峰可能合并或延迟更多。样本应含压力日。只在平静日比较两条管道，会低估分叉。与<a href="/quant/latency-budget">延迟预算</a>对齐：低频因子研究用 SIP 日度质量足够；中频执行研究需要声明是否看到直连。</p>',14)),(E(),s(o,null,{default:e(()=>[n(r,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%7B%22%E7%A0%94%E7%A9%B6%E9%97%AE%E9%A2%98%E8%A6%81%E4%BB%80%E4%B9%88%3F%22%7D%20--%3E%20A%5B%22%E5%85%A8%E5%9B%BD%E4%BB%B7%E6%A0%BC%E8%B4%A8%E9%87%8F%20%2F%20%E6%9C%89%E6%95%88%E4%BB%B7%E5%B7%AE%22%5D%0A%20%20Q%20--%3E%20B%5B%22%E6%9C%AC%E6%89%80%E9%98%9F%E5%88%97%E4%B8%8E%E5%BE%AE%E8%A7%82%E7%BB%93%E6%9E%84%22%5D%0A%20%20Q%20--%3E%20C%5B%22%E4%B8%A4%E6%9D%A1%E7%AE%A1%E9%81%93%E7%9A%84%E5%88%86%E5%8F%89%E6%9C%AC%E8%BA%AB%22%5D%0A%20%20A%20--%3E%20A2%5B%22%E7%94%A8%20SIP%20%E6%88%96%E5%AE%98%E6%96%B9%E7%A3%81%E5%B8%A6%2C%20%E4%B8%AD%E7%82%B9%E4%B8%8E%E6%88%90%E4%BA%A4%E5%90%8C%E6%BA%90%22%5D%0A%20%20B%20--%3E%20B2%5B%22%E5%BF%85%E9%A1%BB%E7%9B%B4%E8%BF%9E%20L2%20%E6%88%96%20L3%22%5D%0A%20%20C%20--%3E%20C2%5B%22%E5%90%8C%E6%97%B6%E8%AE%A2%E9%98%85%2C%20%E5%85%88%E5%AF%B9%E6%97%B6%2C%20%E6%A0%B7%E6%9C%AC%E5%90%AB%E5%8E%8B%E5%8A%9B%E6%97%A5%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<h3 id="成交磁带与报价馈送可以不是同一源" tabindex="-1">成交磁带与报价馈送可以不是同一源 <a class="header-anchor" href="#成交磁带与报价馈送可以不是同一源" aria-label="Permalink to &quot;成交磁带与报价馈送可以不是同一源&quot;">​</a></h3><p>有人用直连报价、用 SIP 成交（或 TAQ）。时间对齐更难，方向分类会混。合法设计是：报价与成交同一源，或成交用官方成交回放、报价用直连并接受两者时钟已校准。混源而不校准，Lee–Ready / EMO 的输入先坏。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>SIP 是汇总后再广播，物理上多一跳，且要等各所到达汇总点。直连少一跳，但全国最优需要用户自己拼，拼的完整取决于买了哪些所。制度把保护绑定在 SIP 的 NBBO 上时，直连上的「更优」报价可能尚未成为保护报价。于是出现经济上可成交、监管上未保护的价格。暗池中点若钉 SIP 中点，锚更慢；若钉直连中点，锚更快但与监管参照分叉。市场设计课的中点协议在这里落到具体馈送。</p><p><span class="marginnote">分叉不是 <a href="/quant/kyle-model">Kyle</a> 的知情优势本身。它可以来自物理延迟。要把信息与管道延迟分开，必须先对时，下一课开始。</span></p>',5)),(E(),s(o,null,{default:e(()=>[n(r,{id:"mermaid-56",class:"mermaid",graph:"flowchart%20LR%0A%20%20E%5B%22%E5%90%84%E4%BA%A4%E6%98%93%E6%89%80%E6%92%AE%E5%90%88%22%5D%20--%3E%20D%5B%22%E7%9B%B4%E8%BF%9E%E9%A6%88%E9%80%81%22%5D%0A%20%20E%20--%3E%20S%5B%22SIP%20%E6%B1%87%E6%80%BB%E5%B9%BF%E6%92%AD%22%5D%0A%20%20D%20--%3E%20F%5B%22%E7%94%A8%E6%88%B7%E5%90%88%E6%88%90%E6%9C%80%E4%BC%98%22%5D%0A%20%20S%20--%3E%20N%5B%22%E7%9B%91%E7%AE%A1%20NBBO%22%5D%0A%20%20F%20--%3E%20X%5B%22%E5%8F%AF%E8%83%BD%E4%B8%8E%20N%20%E7%9F%AD%E6%9A%82%E5%88%86%E5%8F%89%22%5D%0A%20%20N%20--%3E%20X%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<h3 id="压力日才是分叉的识别样本" tabindex="-1">压力日才是分叉的识别样本 <a class="header-anchor" href="#压力日才是分叉的识别样本" aria-label="Permalink to &quot;压力日才是分叉的识别样本&quot;">​</a></h3><p>平静日两条管道几乎重合，会得出「用 SIP 就够」的假结论。容量节流与汇总延迟在高峰出现。对照必须含压力日，并按成交强度分层。</p><p><span class="marginnote">数字实例：若 SIP 比直连慢 5–10 毫秒，平静行情里中点几乎不动，两条管道算出的有效价差相同；但高频事件里中点几毫秒内就能跨一个 tick，用过时的 SIP 中点去标记直连成交，测得成本可能整整个 tick 地偏高或偏低。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>欧洲、新兴市场的「官方合并行情」与 SIP 法律地位不同。加密各所无全国 SIP，只有各所直连与聚合网站，聚合网站更接近未受监管的 SIP 模仿。本课不提供共址或购买哪些直连的清单。下一课把时间戳字段从源里拆出来。</p><p><span class="marginnote">用直连报价配 SIP 成交而不校准时钟，方向分类会先坏。同源或成对校准，是方法而不是偏好。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>SIP 提供覆盖与监管参照，直连提供本所速度与深度；不是单纯快慢。</li><li>有效价差的中点必须与成交声明同源，或做跨源对照。</li><li>分叉在压力日更大；平静日比较会低估。</li><li>混用报价源与成交源会先毁掉方向分类。</li><li>中点协议钉哪一条管道，决定锚的时钟。</li><li>出处：Reg NMS 与 SIP 的公开制度说明；Ding, Hanna and Hendershott 等对 SIP 延迟的经验工作；Hasbrouck 对数据源的处理。</li></ul>',8))])}const _=B(d,[["render",p]]);export{m as __pageData,_ as default};
